    public class ClaimApprovalService : IClaimApprovalService
    {
        public ClaimApprovalResponse ApproveClaim(ClaimApprovalRequest request)
        {
            var timestamp = DateTime.UtcNow.ToString("o");

            if (request.ClaimAmount <= 250.0m && request.RiskScore < 0.3m && 
                (request.DamageType == "SCREEN" || request.DamageType == "SCREEN_CRACK" || request.DamageType == "DISPLAY_DAMAGE"))
            {
                return new ClaimApprovalResponse
                {
                    ApprovalStatus = "APPROVED",
                    ReasonCode = "AUTO_APPROVED",
                    Timestamp = timestamp
                };
            }
            else
            {
                return new ClaimApprovalResponse
                {
                    ApprovalStatus = "REJECTED",
                    ReasonCode = "MANUAL_REVIEW_REQUIRED",
                    Timestamp = timestamp
                };
            }
        }
    }
